	var sh;
	var st;
	var dt;
	var s0;
	var s1;
	var s2;
	var o;
	var s;
	var x;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 3, 1, 2 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	x = ndarray( dt, zeros( numel( sh ), dt ), sh, st, o, ord );
	s0 = new Slice( 0, 2 );
	s1 = new Slice( null, null );
	s2 = new Slice( null, null );
